import{_ as a,o as d,c as e,a2 as n}from"./chunks/framework.Cd7uensT.js";const b=JSON.parse('{"title":"IP 地址管理（IPAM）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/ipam-management.md","filePath":"guide/features/ipam-management.md","lastUpdated":1794561975000}'),s={name:"guide/features/ipam-management.md"};function r(o,t,i,l,h,p){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="ip-地址管理-ipam" tabindex="-1">IP 地址管理（IPAM） <a class="header-anchor" href="#ip-地址管理-ipam" aria-label="Permalink to &quot;IP 地址管理（IPAM）&quot;">​</a></h1><p>IPAM 模块用于规划网段、分配 IP 地址并维护「IP ↔ 设备」的对应关系，替代传统的 Excel 台账方式。</p><blockquote><p><strong>版本要求</strong>：IP 与设备关联能力需 <strong>v2.8.3 及以上</strong>；定时探测调度需 <strong>v2.8.4 及以上</strong>。</p></blockquote><h2 id="功能定位" tabindex="-1">功能定位 <a class="header-anchor" href="#功能定位" aria-label="Permalink to &quot;功能定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>解决的问题</th></tr></thead><tbody><tr><td>网段规划与嵌套</td><td>用树形结构表达「数据中心 → 业务域 → 子网」的层次划分</td></tr><tr><td>IP 地址台账</td><td>替代 Excel，记录每个地址的状态、用途、绑定设备</td></tr><tr><td>设备双向关联</td><td>从 IP 查设备，也从设备查 IP</td></tr><tr><td>在线探测</td><td>感知地址是否存活，发现台账与实际不符的地址</td></tr><tr><td>冲突检测</td><td>新建网段时自动发现与已有网段的重叠</td></tr></tbody></table><h2 id="进入模块" tabindex="-1">进入模块 <a class="header-anchor" href="#进入模块" aria-label="Permalink to &quot;进入模块&quot;">​</a></h2><p>菜单位置：<strong>IP地址管理 → 网段与IP</strong></p><blockquote><p><strong>权限说明</strong>：IPAM 模块当前<strong>未注册独立权限码</strong>，所有已登录用户均可访问。如需按角色隔离，请参见 <a href="/idc_assest-docs/api/permissions.html#未纳入权限码的模块">权限接口 - 未纳入权限码的模块</a>。</p></blockquote><h2 id="网段管理" tabindex="-1">网段管理 <a class="header-anchor" href="#网段管理" aria-label="Permalink to &quot;网段管理&quot;">​</a></h2><h3 id="创建网段" tabindex="-1">创建网段 <a class="header-anchor" href="#创建网段" aria-label="Permalink to &quot;创建网段&quot;">​</a></h3><ol><li>进入「网段与IP」页面</li><li>点击「新建网段」</li><li>填写关键信息：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>填写建议</th></tr></thead><tbody><tr><td>网段名称</td><td>是</td><td>使用业务语义命名，如「生产业务网-A栋」</td></tr><tr><td>CIDR</td><td>是</td><td>如 <code>10.10.0.0/24</code> 或 <code>2001:db8::/32</code>，支持下述两种地址族</td></tr><tr><td>网关</td><td>否</td><td>建议填写，便于后续识别</td></tr><tr><td>VLAN ID</td><td>否</td><td>与交换机配置对齐</td></tr><tr><td>DNS</td><td>否</td><td>多个用逗号分隔</td></tr><tr><td>默认用途</td><td>否</td><td>设为 <code>management</code> 后，该网段内新建 IP 时自动推荐为带外管理地址</td></tr><tr><td>父网段</td><td>否</td><td>用于构建层级结构</td></tr></tbody></table><ol start="4"><li>保存前系统自动执行 CIDR 解析与冲突检测，冲突时给出具体的冲突网段名称与 CIDR</li></ol><h3 id="cidr-解析规则" tabindex="-1">CIDR 解析规则 <a class="header-anchor" href="#cidr-解析规则" aria-label="Permalink to &quot;CIDR 解析规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址族</th><th>可用主机数计算</th><th>说明</th></tr></thead><tbody><tr><td>IPv4</td><td><code>2^(32-前缀) - 2</code></td><td>扣除网络地址与广播地址</td></tr><tr><td>IPv6</td><td><code>2^(128-前缀)</code></td><td>不使用广播地址概念</td></tr></tbody></table><blockquote><p>IPv6 的 <code>/64</code> 网段可用主机数为 <code>2^64</code>，数值超出 JavaScript Number 精度范围，系统统一以字符串存储与展示。</p></blockquote><h3 id="网段嵌套规则" tabindex="-1">网段嵌套规则 <a class="header-anchor" href="#网段嵌套规则" aria-label="Permalink to &quot;网段嵌套规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>是否允许</th></tr></thead><tbody><tr><td>在已有网段内创建更小的子网段</td><td><strong>允许</strong></td></tr><tr><td>创建与已有网段完全相同的 CIDR</td><td>拒绝</td></tr><tr><td>创建与已有网段部分重叠的 CIDR</td><td>拒绝</td></tr><tr><td>创建覆盖已有网段的大网段</td><td>拒绝</td></tr><tr><td>跨地址族（IPv4 与 IPv6）</td><td>不参与冲突检测</td></tr></tbody></table><h3 id="层级统计规则" tabindex="-1">层级统计规则 <a class="header-anchor" href="#层级统计规则" aria-label="Permalink to &quot;层级统计规则&quot;">​</a></h3><p>父网段的已用 IP 数<strong>包含所有后代网段</strong>的已用数（递归累加）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10.0.0.0/16（父）  已用 240</span></span>
<span class="line"><span>  ├─ 10.0.1.0/24   已用 200</span></span>
<span class="line"><span>  └─ 10.0.2.0/24   已用 40</span></span></code></pre></div><p>因此，父网段使用率反映的是整个地址池的实际占用，而非仅父网段直接挂载的 IP。</p><h3 id="大规模网段处理" tabindex="-1">大规模网段处理 <a class="header-anchor" href="#大规模网段处理" aria-label="Permalink to &quot;大规模网段处理&quot;">​</a></h3><p>对于 <code>/16</code> 及以上的 IPv4 网段，系统不会一次性生成全部 IP 记录：</p><ul><li>网段创建时按需生成，<code>autoGenerated</code> 标记是否已完成生成</li><li>网段详情页的统计按钮触发<strong>按需统计</strong>（<code>GET /subnets/{id}/stats</code>），避免全量扫描</li><li>IPv6 网段恒不自动生成（<code>autoGenerated = false</code>），需按实际分配逐个添加</li></ul><h2 id="ip-地址管理" tabindex="-1">IP 地址管理 <a class="header-anchor" href="#ip-地址管理" aria-label="Permalink to &quot;IP 地址管理&quot;">​</a></h2><h3 id="ip-状态" tabindex="-1">IP 状态 <a class="header-anchor" href="#ip-状态" aria-label="Permalink to &quot;IP 状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>使用建议</th></tr></thead><tbody><tr><td>空闲</td><td>可使用</td><td>新设备分配时优先选择</td></tr><tr><td>已使用</td><td>已分配</td><td>通常由绑定操作自动设置</td></tr><tr><td>预留</td><td>预留给特定用途</td><td>如预留扩展、灾备</td></tr><tr><td>网关</td><td>网关地址</td><td>系统级保护，绑定中的 IP 不可改为该状态</td></tr><tr><td>排除</td><td>排除地址</td><td>如 VRRP 虚拟地址、不可扫描的地址</td></tr></tbody></table><h3 id="状态自动驱动机制" tabindex="-1">状态自动驱动机制 <a class="header-anchor" href="#状态自动驱动机制" aria-label="Permalink to &quot;状态自动驱动机制&quot;">​</a></h3><p>这是 IPAM 的核心设计，避免用户漏改状态导致台账失真：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IP 状态 = free，执行绑定 → 状态自动变 used，标记 statusAutoDriven = true</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                    执行解绑 ────┴──→ 因 statusAutoDriven = true，状态自动回退 free</span></span></code></pre></div><table tabindex="0"><thead><tr><th>场景</th><th><code>statusAutoDriven</code></th><th>解绑后状态</th></tr></thead><tbody><tr><td>绑定前为 <code>free</code></td><td>置 <code>true</code></td><td>自动回退 <code>free</code></td></tr><tr><td>用户手动改过状态</td><td>置 <code>false</code></td><td>保持用户设置的状态不变</td></tr></tbody></table><blockquote><p>用户手动修改状态即视为「接管」该 IP 的状态控制权，系统不再自动干预。</p></blockquote><h3 id="ip-类型-iptype" tabindex="-1">IP 类型（ipType） <a class="header-anchor" href="#ip-类型-iptype" aria-label="Permalink to &quot;IP 类型（ipType）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>中文</th><th>典型场景</th></tr></thead><tbody><tr><td><code>management</code></td><td>带外管理</td><td>BMC / iDRAC / iLO 管理口</td></tr><tr><td><code>business</code></td><td>带内业务</td><td>操作系统业务网卡</td></tr><tr><td><code>public</code></td><td>公网</td><td>NAT 映射后的公网地址</td></tr><tr><td><code>storage</code></td><td>存储网</td><td>存储专用网络</td></tr><tr><td><code>other</code></td><td>其他</td><td>特殊用途</td></tr></tbody></table><p><strong>网段默认用途的继承</strong>：若网段设置了 <code>purpose</code>，在该网段内新建 IP 或绑定设备时，系统自动推荐该值，减少重复填写。</p><h3 id="自定义标签" tabindex="-1">自定义标签 <a class="header-anchor" href="#自定义标签" aria-label="Permalink to &quot;自定义标签&quot;">​</a></h3><p><code>customTag</code> 为自由文本，用于标注业务语义，如：</p><ul><li><code>VIP</code> — 虚拟 IP</li><li><code>主备</code> — 主备切换组</li><li><code>cluster</code> — 集群地址</li><li><code>临时</code> — 临时分配</li></ul><h3 id="主-ip-标记" tabindex="-1">主 IP 标记 <a class="header-anchor" href="#主-ip-标记" aria-label="Permalink to &quot;主 IP 标记&quot;">​</a></h3><p>每台设备<strong>全局最多一个</strong>主 IP（<code>isPrimaryForDevice</code>），在表格中以 ★ 标识。</p><p>典型场景：一台服务器有管理 IP、业务 IP、存储 IP，其中管理 IP 通常设为主 IP，便于其他模块（如工单、拓扑）引用「设备地址」时优先取用。</p><p>设置新的主 IP 时，原主 IP 自动取消标记。</p><h3 id="绑定与解绑" tabindex="-1">绑定与解绑 <a class="header-anchor" href="#绑定与解绑" aria-label="Permalink to &quot;绑定与解绑&quot;">​</a></h3><p><strong>单个绑定</strong>：</p><ol><li>在 IP 列表中选择目标地址</li><li>点击「绑定设备」</li><li>选择设备，可选填 IP 类型与自定义标签</li><li>如需设为主 IP，勾选「设为主 IP」</li></ol><p><strong>批量绑定</strong>：选中多个 IP 后统一指定目标设备，适用于一台服务器上多个连续的地址。</p><p><strong>解绑</strong>：点击「解绑」，系统按状态自动驱动规则处理 IP 状态。</p><h3 id="设备删除的级联处理" tabindex="-1">设备删除的级联处理 <a class="header-anchor" href="#设备删除的级联处理" aria-label="Permalink to &quot;设备删除的级联处理&quot;">​</a></h3><p>删除设备时，IPAM 自动执行：</p><table tabindex="0"><thead><tr><th>处理项</th><th>行为</th></tr></thead><tbody><tr><td>绑定关系</td><td>清空所有关联 IP 的 <code>deviceId</code>、<code>networkCardId</code>、主 IP 标记</td></tr><tr><td>状态回退</td><td><code>statusAutoDriven = true</code> 的 IP 自动回退 <code>free</code></td></tr><tr><td>用户干预的 IP</td><td>手动设置过状态的 IP 保持原状态</td></tr></tbody></table><p>这避免了设备删除后遗留大量「已使用但无主」的僵尸地址。</p><h2 id="在线探测" tabindex="-1">在线探测 <a class="header-anchor" href="#在线探测" aria-label="Permalink to &quot;在线探测&quot;">​</a></h2><h3 id="探测原理" tabindex="-1">探测原理 <a class="header-anchor" href="#探测原理" aria-label="Permalink to &quot;探测原理&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对目标 IP 发起 ICMP Ping</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>   ┌────┴────┐</span></span>
<span class="line"><span> 成功       失败</span></span>
<span class="line"><span>   │          │</span></span>
<span class="line"><span>   标记      按配置端口列表尝试 TCP 连接</span></span>
<span class="line"><span>  online       │</span></span>
<span class="line"><span>        ┌─────┴─────┐</span></span>
<span class="line"><span>      任一端口通   全部失败</span></span>
<span class="line"><span>        │            │</span></span>
<span class="line"><span>      online       offline</span></span></code></pre></div><ul><li><code>probeMethod</code> 记录成功方式：<code>ping</code>、<code>tcp</code>、<code>both</code></li><li><code>probeLatency</code> 记录延迟（毫秒）</li><li>未探测过的地址为 <code>unknown</code></li></ul><h3 id="探测配置" tabindex="-1">探测配置 <a class="header-anchor" href="#探测配置" aria-label="Permalink to &quot;探测配置&quot;">​</a></h3><p>在网段详情页点击「探测设置」：</p><table tabindex="0"><thead><tr><th>配置项</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>启用 Ping</td><td>开</td><td>关闭后仅使用 TCP 探测</td></tr><tr><td>TCP 端口</td><td><code>22, 80, 443, 161, 3389</code></td><td>Ping 被防火墙拦截时的回退探测</td></tr><tr><td>超时</td><td>1500 ms</td><td>最小 200 ms</td></tr><tr><td>并发数</td><td>20</td><td>范围 1~100，过大可能被设备侧限流</td></tr></tbody></table><h3 id="探测方式" tabindex="-1">探测方式 <a class="header-anchor" href="#探测方式" aria-label="Permalink to &quot;探测方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>入口</th><th>适用场景</th></tr></thead><tbody><tr><td>单地址探测</td><td>IP 行操作</td><td>排查单个地址</td></tr><tr><td>批量探测</td><td>选中多个 IP</td><td>核对某批次地址</td></tr><tr><td>按网段探测</td><td>网段详情页「探测网段」</td><td>梳理整个子网</td></tr><tr><td>全量探测</td><td>探测设置面板「立即执行」</td><td>定期全面核对</td></tr></tbody></table><h3 id="定时探测" tabindex="-1">定时探测 <a class="header-anchor" href="#定时探测" aria-label="Permalink to &quot;定时探测&quot;">​</a></h3><p>在「探测设置 → 定时探测」中开启并配置 Cron 表达式，默认 <code>0 3 * * *</code>（每天凌晨 3 点）。</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>热重载</td><td>保存后调度器立即生效，无需重启服务</td></tr><tr><td>部分更新</td><td>可只改开关或只改表达式，未提交项保持原值</td></tr><tr><td>执行方式</td><td>后台异步执行，不阻塞界面</td></tr></tbody></table><blockquote><p><strong>部署注意</strong>：定时任务由进程内 node-cron 驱动，<strong>服务重启期间不会执行</strong>。多实例部署时每个实例都会触发，需通过配置保证仅一个实例启用。</p></blockquote><h2 id="冲突排查" tabindex="-1">冲突排查 <a class="header-anchor" href="#冲突排查" aria-label="Permalink to &quot;冲突排查&quot;">​</a></h2><h3 id="网段冲突" tabindex="-1">网段冲突 <a class="header-anchor" href="#网段冲突" aria-label="Permalink to &quot;网段冲突&quot;">​</a></h3><p>创建网段时如提示冲突，提示信息会指明冲突的网段名称与 CIDR。处理方式：</p><table tabindex="0"><thead><tr><th>情况</th><th>处理</th></tr></thead><tbody><tr><td>确实是新的子网划分</td><td>调整父网段选择，或修改 CIDR 前缀长度</td></tr><tr><td>误将已存在网段重复创建</td><td>直接使用已有网段</td></tr><tr><td>历史数据本身存在重叠</td><td>通过 <code>GET /api/ipam/conflicts</code> 全局排查后修正</td></tr></tbody></table><h3 id="ip-冲突" tabindex="-1">IP 冲突 <a class="header-anchor" href="#ip-冲突" aria-label="Permalink to &quot;IP 冲突&quot;">​</a></h3><p>IP 地址在网段内唯一。若导入的历史台账中存在重复地址：</p><ol><li>优先保留有设备绑定的记录</li><li>无绑定的重复记录可直接删除</li><li>确认无误后重新执行探测核对在线状态</li></ol><h2 id="与设备管理的联动" tabindex="-1">与设备管理的联动 <a class="header-anchor" href="#与设备管理的联动" aria-label="Permalink to &quot;与设备管理的联动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>位置</th><th>用途</th></tr></thead><tbody><tr><td>设备详情 → IP 信息</td><td>设备管理 / 设备详情抽屉</td><td>查看该设备绑定的所有 IP</td></tr><tr><td>IP 列表 → 设备列</td><td>IPAM 页面</td><td>点击设备名跳转设备详情</td></tr><tr><td>设备删除</td><td>设备管理</td><td>自动解绑并回退 IP 状态</td></tr></tbody></table><h2 id="典型使用流程" tabindex="-1">典型使用流程 <a class="header-anchor" href="#典型使用流程" aria-label="Permalink to &quot;典型使用流程&quot;">​</a></h2><h3 id="新机房上线" tabindex="-1">新机房上线 <a class="header-anchor" href="#新机房上线" aria-label="Permalink to &quot;新机房上线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 创建机房记录 → 创建网段（按业务域划分，设置默认用途）</span></span>
<span class="line"><span>2. 创建设备 → 录入设备基础信息</span></span>
<span class="line"><span>3. 为设备绑定 IP（或批量导入设备后批量绑定）</span></span>
<span class="line"><span>4. 开启定时探测 → 次日核对在线状态</span></span>
<span class="line"><span>5. 对异常地址逐个排查（可能为台账错误或设备下线）</span></span></code></pre></div><h3 id="日常地址分配" tabindex="-1">日常地址分配 <a class="header-anchor" href="#日常地址分配" aria-label="Permalink to &quot;日常地址分配&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 在网段中筛选「空闲」状态的 IP</span></span>
<span class="line"><span>2. 优先选择与业务网段用途匹配的地址</span></span>
<span class="line"><span>3. 绑定到目标设备，填写自定义标签</span></span>
<span class="line"><span>4. 首次分配建议设为主 IP 以便其他模块引用</span></span></code></pre></div><h3 id="设备下架" tabindex="-1">设备下架 <a class="header-anchor" href="#设备下架" aria-label="Permalink to &quot;设备下架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 在设备管理中将设备转入空闲设备</span></span>
<span class="line"><span>2. IPAM 中对应 IP 的绑定关系保留（设备尚未删除）</span></span>
<span class="line"><span>3. 确认设备报废后删除设备 → IP 自动解绑并回退为空闲</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：旧版本设备表单里的 IP 地址字段还需要填吗？</strong></p><p>不需要。v2.8.3 已将 <code>Device.ipAddress</code> 迁移至 IPAM 表，旧字段保留但已废弃。所有地址维护请统一在 IPAM 模块中进行。</p><p><strong>Q：为什么父网段的使用率比子网段还高？</strong></p><p>父网段统计为递归累加值，包含所有后代网段的已用数。若父网段直接挂载的 IP 较少但子网段占用较多，父网段使用率会相应偏高，这是预期行为。</p><p><strong>Q：探测结果显示 offline，但设备实际在线？</strong></p><p>常见原因：ICMP 被安全策略拦截，且配置的 TCP 端口在目标设备上均未开放。处理：调整 TCP 端口列表，或在网络中放通 ICMP。</p><p><strong>Q：能否把一个 IP 绑定到多台设备？</strong></p><p>不能。IP 与设备为一对一关系。如需表达 VIP 等共享地址场景，建议使用 <code>customTag</code> 标注并在描述中说明主备关系。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/idc_assest-docs/api/ipam.html">IPAM 接口文档</a></li><li><a href="./device-management.html">设备管理</a></li><li><a href="./idle-device-management.html">空闲设备管理</a></li></ul>`,92)])])}const u=a(s,[["render",r]]);export{b as __pageData,u as default};
